import React from 'react'

/** Generated by `npm run brand` from Frontend/Shared/branding. */
export default function BrandMark({ full = false, size = 28, chip = false, alt = 'CricAll logo' }) {
  const image = (
    <img
      src={full ? '/brand/logo-full.png' : '/brand/emblem.png'}
      alt={alt}
      width={size}
      height={size}
      className="block h-full w-full object-contain"
    />
  )
  if (!chip) {
    return (
      <span className="inline-block shrink-0" style={{ width: size, height: size }}>
        {image}
      </span>
    )
  }
  return (
    <span
      className="inline-flex shrink-0 items-center justify-center rounded-lg bg-white p-1 shadow-sm"
      style={{ width: size + 8, height: size + 8 }}
    >
      {image}
    </span>
  )
}
